function icon(name,extra=''){return '<svg class="icon '+extra+'" viewBox="0 0 24 24" aria-hidden="true"><path d="'+(paths[name]||paths.spark)+'"/></svg>'}
function decorate(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon))}
decorate();
function checks(items){return items.map(t=>'<li>'+icon('check')+'<span>'+t+'</span></li>').join('')}
function windowFrame(title,content){return '<div class="demo-window"><div class="demo-titlebar"><span class="browser-dots"><i></i><i></i><i></i></span><strong>'+title+'</strong>'+icon('lock')+'</div>'+content+'</div>'}
