let currentCap='public';const capButtons=[...document.querySelectorAll('[data-cap]')];
function setCapability(key){currentCap=key;const c=capabilities[key];document.querySelector('#platform-panel').classList.toggle('builder-mode',key==='cms');capButtons.forEach(b=>{const active=b.dataset.cap===key;b.setAttribute('aria-selected',active);b.tabIndex=active?0:-1});document.querySelector('#platform-panel').setAttribute('aria-labelledby','tab-'+key);document.querySelector('#cap-badge').textContent=c.badge;document.querySelector('#cap-title').textContent=c.title;document.querySelector('#cap-description').textContent=c.description;document.querySelector('#cap-outcomes').innerHTML=checks(c.outcomes);document.querySelector('#cap-scope').textContent=c.scope;document.querySelector('.cap-details').open=false;document.querySelector('#demo-instruction').textContent=c.instruction;document.querySelector('#demo-content').innerHTML=key==='cms'?Builder.markup():c.demo();if(key==='cms')Builder.init();else wireDemo(key)}
function notice(text){return '<div class="demo-notice">'+icon('check')+'<span>'+text+'</span></div>'}
function wireDemo(key){if(key==='public')document.querySelector('#demo-explore').onclick=()=>{document.querySelector('#public-result').innerHTML=notice('Insights are easy to find. Clear pathways bring your work into focus.')};if(key==='cms')document.querySelector('#demo-publish').onclick=()=>{document.querySelector('#publish-result').innerHTML=notice('Sample published. An approachable workflow for your editors.');const b=document.querySelector('#demo-publish');b.innerHTML=icon('check')+' Sample published';b.disabled=true};if(key==='portal')document.querySelector('#demo-resource').onclick=()=>document.querySelector('#portal-result').innerHTML=notice('Sample resource opened. Real access will be checked on the server.');if(key==='micro')document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-theme]').forEach(n=>n.setAttribute('aria-pressed',n===b));document.querySelector('#micro-preview').style.background={lilac:'#ece8fb',coral:'#ffebe5',mint:'#e1f3ec'}[b.dataset.theme]});if(key==='crm')document.querySelector('#demo-crm').onclick=()=>{document.querySelectorAll('[data-crm]').forEach(n=>n.classList.add('completed'));document.querySelector('#crm-result').textContent='Sample flow complete: enquiry → validation → CRM. No real data was sent.';document.querySelector('#demo-crm').innerHTML=icon('check')+' Sample connected';document.querySelector('#demo-crm').disabled=true}}
capButtons.forEach((b,i)=>{b.onclick=()=>setCapability(b.dataset.cap);b.onkeydown=e=>{let target;if(e.key==='ArrowRight')target=(i+1)%5;if(e.key==='ArrowLeft')target=(i+4)%5;if(e.key==='Home')target=0;if(e.key==='End')target=4;if(target!==undefined){e.preventDefault();setCapability(capButtons[target].dataset.cap);capButtons[target].focus()}}});setCapability(location.hash==='#builder'?'cms':'public');if(location.hash==='#builder')requestAnimationFrame(()=>document.querySelector('#builder').scrollIntoView({block:'start'}));
const layers={astro:{icon:'globe',label:'ASTRO / PUBLIC FRONTEND',title:'Fast pages. Focused interaction.',text:'Astro delivers most content as lightweight HTML and adds interactive features only where needed. It is a strong fit for a content-led public website and reusable microsites.',analogy:'Think of it as the storefront: welcoming, easy to navigate and quick to open.',links:[['Astro documentation','https://docs.astro.build/en/concepts/islands/']]},cms:{icon:'layers',label:'STORYBLOK / CANDIDATE TO VALIDATE',title:'An approachable content studio.',text:'A visual, component-based CMS could let editors assemble approved pages without code. Storyblok remains a candidate until real editors confirm preview, permissions, approvals, migration and licensing fit.',analogy:'Think of it as a set of building blocks: freedom to publish within a consistent brand.',links:[['Storyblok documentation','https://www.storyblok.com/docs']]},portal:{icon:'people',label:'OWNED PORTAL / FRONTEND EXPERIENCE',title:'A front door for your members.',text:'A dedicated interface presents member resources and calls Django services for identity and access. The backend decides who can see what. The portal frontend rendering approach is still to be agreed.',analogy:'Think of it as the members’ lounge: a familiar place with the right access checks.',links:[]},django:{icon:'shield',label:'DJANGO / PYTHON · BACKEND DIRECTION',title:'The engine behind the experience.',text:'Align with the backend team’s stated Django / Python direction. The backend handles sign-in, permission rules, application data and CRM connections. Its owner confirms scope, infrastructure and delivery milestones.',analogy:'Think of it as the operations team: checking access, protecting data and connecting the systems.',links:[['Django documentation','https://docs.djangoproject.com/'],['Python documentation','https://docs.python.org/3/']]}};
function setLayer(key){const l=layers[key];document.querySelectorAll('[data-layer]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.layer===key));document.querySelector('#layer-icon').innerHTML=icon(l.icon);document.querySelector('#layer-label').textContent=l.label;document.querySelector('#layer-title').textContent=l.title;document.querySelector('#layer-text').textContent=l.text;document.querySelector('#layer-links').innerHTML=l.links.map(([title,url])=>'<a href="'+url+'">'+title+' ↗</a>').join('');document.querySelector('#layer-analogy').innerHTML='<small>IN EVERYDAY TERMS</small>'+l.analogy}
document.querySelectorAll('[data-layer]').forEach(b=>b.onclick=()=>setLayer(b.dataset.layer));setLayer('astro');
