let selectedStage=0,selectedWeek=0,tourTimer=null;const stageTrack=document.querySelector('.stage-track');
stages.forEach((s,i)=>{const b=document.createElement('button');b.className='stage-card';b.dataset.stage=i;b.dataset.phase=i<4?'dev':'qa';b.setAttribute('aria-pressed','false');b.setAttribute('aria-label','Stage '+(i+1)+': '+s.name+', weeks '+(i*2+1)+' and '+(i*2+2));b.setAttribute('aria-controls','stage-title');b.innerHTML='<span class="icon-badge '+(i<4?'lavender':'peach')+'">'+icon(s.icon)+'</span><span class="stage-category">0'+(i+1)+'</span><strong>'+s.name+'</strong><small>Weeks '+String(i*2+1).padStart(2,'0')+'–'+String(i*2+2).padStart(2,'0')+'</small><span class="stage-mini-bar" aria-hidden="true"><i></i><i></i></span>';b.onclick=()=>{stopTour();setStage(i)};stageTrack.append(b)});
function setWeek(i){selectedWeek=i;const w=weeks[i];document.querySelector('#week-title').textContent='Week '+String(i+1).padStart(2,'0')+' · '+w.title;document.querySelector('#week-activity').textContent=w.activity;document.querySelector('#week-outputs').innerHTML=checks(w.outputs);document.querySelector('#week-seo').textContent=w.seo;document.querySelectorAll('[data-week]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.week)===i));document.querySelector('#stage-counter').textContent='Stage '+(selectedStage+1)+' of 6 · Week '+(i+1)+' of 12';document.dispatchEvent(new CustomEvent('proposal-week',{detail:i}))}
function setStage(i,week=i*2){selectedStage=i;const s=stages[i];document.querySelectorAll('[data-stage]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.stage)===i));document.querySelector('#stage-number').textContent='STAGE 0'+(i+1);document.querySelector('#stage-period').textContent='WEEKS '+String(i*2+1).padStart(2,'0')+'–'+String(i*2+2).padStart(2,'0')+' / '+(i<4?'DEVELOPMENT':'QA & LAUNCH');document.querySelector('#stage-title').textContent=s.name;document.querySelector('#stage-summary').textContent=s.summary;document.querySelector('#stage-result').textContent=s.result;document.querySelector('#stage-visual').innerHTML=s.visual();const container=document.querySelector('#stage-weeks');container.replaceChildren();for(let n=i*2;n<i*2+2;n++){const b=document.createElement('button');b.dataset.week=n;b.setAttribute('aria-label','Week '+(n+1)+': '+weeks[n].title);b.setAttribute('aria-controls','week-title');b.innerHTML='<b>W'+String(n+1).padStart(2,'0')+'</b>'+weeks[n].label;b.onclick=()=>{stopTour();setWeek(n)};container.append(b)}document.querySelector('#stage-prev').disabled=i===0;document.querySelector('#stage-next').disabled=i===5;setWeek(week)}
function stopTour(){clearInterval(tourTimer);tourTimer=null;const b=document.querySelector('#tour');b.setAttribute('aria-pressed','false');b.innerHTML=icon('play')+' Guide me through'}
document.querySelector('#tour').onclick=()=>{if(tourTimer){stopTour();return}setStage(0);const b=document.querySelector('#tour');b.setAttribute('aria-pressed','true');b.innerHTML=icon('pause')+' Pause walkthrough';tourTimer=setInterval(()=>{if(selectedStage===5){stopTour();return}setStage(selectedStage+1)},6500)};
document.querySelector('#stage-prev').onclick=()=>{stopTour();setStage(Math.max(0,selectedStage-1))};document.querySelector('#stage-next').onclick=()=>{stopTour();setStage(Math.min(5,selectedStage+1))};document.addEventListener('visibilitychange',()=>{if(document.hidden)stopTour()});setStage(0);
document.querySelector('#print').onclick=()=>window.print();let ticking=false;addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(()=>{const total=document.documentElement.scrollHeight-innerHeight;document.querySelector('.scroll-progress').style.width=(total>0?scrollY/total*100:0)+'%';ticking=false});ticking=true}},{passive:true});
